package mx.elmuelle.pdv;
import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.io.*;import java.nio.charset.StandardCharsets;import org.json.*;
@RunWith(AndroidJUnit4.class) public class CipherDeviceTest {
 @Test public void cipherAndKeystoreRoundtripOnAndroid()throws Exception {android.content.Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();NativeRuntime.initialize(context);String original="{\"texto\":\"Datos sintéticos ñ 😀\"}";String wrapped=NativeRuntime.seal(original);assertFalse(wrapped.contains(original));assertEquals(original,NativeRuntime.unseal(wrapped));File file=new File(context.getCacheDir(),"synthetic-"+System.nanoTime()+".sqlite");String key="1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef";JSONObject opened=new JSONObject(NativeRuntime.command(new JSONObject().put("op","dbOpen").put("path",file.getPath()).put("key",key).toString()));assertTrue(opened.toString(),opened.getBoolean("ok"));int id=opened.getInt("value");assertTrue(new JSONObject(NativeRuntime.command(new JSONObject().put("op","dbExec").put("id",id).put("sql","CREATE TABLE proof(value TEXT); INSERT INTO proof VALUES('synthetic')").toString())).getBoolean("ok"));NativeRuntime.command(new JSONObject().put("op","dbClose").put("id",id).toString());byte[] header=new byte[16];try(InputStream in=new FileInputStream(file)){assertEquals(16,in.read(header));}assertNotEquals("SQLite format 3\u0000",new String(header,StandardCharsets.US_ASCII));JSONObject wrong=new JSONObject(NativeRuntime.command(new JSONObject().put("op","dbOpen").put("path",file.getPath()).put("key","abcdef0123456789abcdef0123456789abcdef0123456789abcdef0123456789").toString()));if(wrong.optBoolean("ok")){int wrongId=wrong.getInt("value");assertFalse(new JSONObject(NativeRuntime.command(new JSONObject().put("op","dbQuery").put("id",wrongId).put("sql","SELECT * FROM proof").put("args",new JSONArray()).put("mode","all").toString())).getBoolean("ok"));NativeRuntime.command(new JSONObject().put("op","dbClose").put("id",wrongId).toString());}file.delete();}
}
